fence(119,296,982,296);for(let y=300;y<560;y+=48){rect(113,y,10,41,'#d6bd8b',2);rect(977,y,10,41,'#d6bd8b',2)}line([[118,302],[118,555]],'#bda471',7);line([[982,302],[982,555]],'#bda471',7);
for(const d of S.dirt){if(d.type==='poop'){ellipse(d.x,d.y,8,5,'#978466');ellipse(d.x,d.y-4,6,4,'#a18b69');ellipse(d.x+1,d.y-8,3,3,'#a18b69')}else{line([[d.x-6,d.y],[d.x,d.y-11],[d.x+3,d.y],[d.x+9,d.y-9]],'#8b9d63',3)}}
for(const f of S.feeders){ellipse(f.x,f.y+17,37,12,'#9da96a40');ellipse(f.x,f.y+9,33,12,'#ad8652');ellipse(f.x,f.y+6,30,10,f.food>0?'#d9b65d':'#998368');poly([[f.x-21,f.y+4],[f.x-10,f.y-28],[f.x+10,f.y-28],[f.x+21,f.y+4]],'#b19060');ellipse(f.x,f.y-28,10,4,'#d4b17a');rect(f.x-22,f.y+25,44,4,'#b2bd8e',2);rect(f.x-22,f.y+25,44*f.food/100,4,'#7d965b',2)}ellipse(790,416,55,18,'#9ca67730');rect(742,385,96,37,'#9baba0',14);ellipse(790,389,48,16,'#becbc1');ellipse(790,389,42,12,S.water>0?'#89bfd0':'#9eab9e');if(S.water>0)line([[768,386],[795,383],[811,385]],'#d2e8de',2);
