function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(!paused&&!document.hidden){acc+=dt;while(acc>=1){tick();acc--}walking+=dt;if(typeof playerStep==='function')playerStep(dt);for(const c of S.chickens){if(c.state!=='잠'){const d=Math.hypot(c.tx-c.x,c.ty-c.y);if(d>3){const sp=Math.min(d,dt*43);c.x+=(c.tx-c.x)/d*sp;c.y+=(c.ty-c.y)/d*sp}}}shots=shots.filter(s=>{s.age+=dt;if(s.age>=.42){impact(s);return false}return true});particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=100*dt;return p.life>0})}ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,cv.width,cv.height);if(typeof prepareView==='function')prepareView();if(view==='farm')farmDraw(walking);else if(view==='shop')shopDraw();else if(view==='village'&&typeof villageDraw==='function')villageDraw(walking);else mountainDraw();if(typeof drawCleaningPreview==='function')drawCleaningPreview();if(typeof drawPlayer==='function')drawPlayer(walking);for(const s of shots){const u=s.age/.42;ellipse(550+(s.x-550)*u,565+(s.y-565)*u-Math.sin(u*Math.PI)*110,8,11,eggColors[s.egg.tier])}for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*2);if(p.text)text(p.text,p.x,p.y,22,p.color);else ellipse(p.x,p.y,3,3,p.color);ctx.globalAlpha=1}requestAnimationFrame(frame)}
